package strings.assigment_problems;
public class LibraryIsbnNormalizerValidator { static String normalizeCode(String raw){String s=raw.trim();return s.length()>=3?s.substring(0,3).toUpperCase()+s.substring(3):s.toUpperCase();} static String validateAndFormat(String code){if(code.length()!=13)return"Invalid: wrong length";for(int i=0;i<3;i++)if(!Character.isLetter(code.charAt(i)))return"Invalid: publisher code must be 3 letters";for(int i=3;i<13;i++)if(!Character.isDigit(code.charAt(i)))return"Invalid: body must be digits";return new StringBuilder("[").append(code,0,3).append("] YEAR: 20").append(code,3,7).append(" | CATALOG: ").append(code,7,13).toString();} public static void main(String[]a){String c=normalizeCode(" pen2026004251 ");System.out.println(validateAndFormat(c));}}